import type { Plugin } from "../../kernel/types";

const plugin: Plugin = {
  id: "stable-plugin",
  name: "Stable Plugin",
  version: "1.0.0",
  onLoad(ctx) {
    ctx.register({
      kind: "tool",
      tool: {
        name: "stable_value",
        version: "1.0.0",
        description: "Returns the stable value 18.",
        permissions: [],
        sideEffect: "none",
        parameters: { type: "object", properties: {}, additionalProperties: false },
        outputSchema: { type: "object", properties: { value: { type: "number" } }, required: ["value"] },
        async handler(_args, _tctx) {
          return { ok: true, data: { value: 18 } };
        },
      },
    });
  },
};

export default plugin;

